export enum Kind {
	Login = "login",
	CreditCard = "creditCard",
}

export interface Page<T> {
	items: T[];
	next?: string;
}

export type Action = 
	| { type: "lock", content?: undefined }
	| { type: "open", content: string }
	| { type: "maybeOpen", content?: string }
	| { type: "move", content: {
	from: number;
	to?: number;
}}
	| { type: "nested", content: Action };

export interface Item {
	id: ItemId;
	count: number;
	icon?: string;
	pinned?: boolean;
	cleared?: string | null;
	kind: Kind;
	tags: string[];
	byIndex: Record<number, Kind>;
	byKind: Record<Kind, string>;
	children: Item[];
	point: [number, number];
	nothing: undefined;
	"kebab-key": string;
	page: Page<Kind>;
	action: Action;
	bytes: [number, number, number, number, number, number];
	empty: [];
	letter: string;
	byLetter: Record<string, number>;
	pages: Record<string, Page<Kind>>;
	lowercased: Record<string, number>;
	label?: string;
	child?: Page<Kind>;
	constructor?: string;
	fallback?: Page<Kind> | null;
	toString?: boolean;
	nothingTwice?: undefined | null;
}

export interface LiteralA {
	kind?: "a";
}

export interface LiteralB {
	kind?: "b";
}

